def purpose(member):
    owner, name, kind = member["owner"], member["name"], member["kind"]
    if owner == "CSectionDefinitionBuilder": return BUILDER[name]
    if kind == "Enum": return ENUMS[name]
    if kind == "Type": return TYPE_MEANINGS[name]
    if owner == "CRebarRuleOptions": return OPTIONS[name]
    if name in METHODS.get(owner, {}): return METHODS[owner][name]
    if owner == "CUnitSystem":
        if name == "InitializeDefaults": return "Задаёт программные defaults: input mm/mm²/N/N*mm/MPa/1/mm и Tension, output m/m²/N/N*mm/MPa/1/mm. Не заменяет обязательный Config ввод."
        if name == "LoadFromSettings": return "Загружает и проверяет все активные единицы и знаки через общий settings reader."
        if name.startswith("Output") and member.get("resultType") == "String": return "Возвращает текущий output selector " + name.removeprefix("Output") + ", без преобразования или округления данных."
        if name == "InputMomentPerLengthUnit": return "Возвращает единицу пользовательского момента на длину по input force/moment/length settings."
        if "ToInternal" in name: return "Переводит " + name + " во внутренние мм/Н/Н*мм/МПа/1/мм соответствующей размерности, с принятой конвенцией знаков для N/Mx/My."
        if "ToOutput" in name: return "Переводит " + name + " из внутренних единиц в подготовленные output units; сохранённая единица при наличии имеет явный смысл."
    if name in PROPERTIES: return PROPERTIES[name]
    if kind == "Const":
        return {"GEOM_PI": "Число pi как сумма сохраняемых VBE литералов, без изменения Double при компиляции.",
                "GEOM_TOLERANCE": "Геометрический допуск совпадений исходных координат, мм; не округление ключей результатов.",
                "GEOM_MAX_REBAR_COUNT": "Предел представимости счётчика позиций, не обещание доступности памяти для такого массива."}[name]
    raise ValueError("API meaning is missing: " + member["id"])


def parameter_meaning(member, parameter):
    import re
    name, passing = parameter["name"], parameter["passing"]
    if name == "savedUnit" and member["name"] == "OutputFourthPowerLengthToInternal":
        meaning = "Базовая единица длины сохранённого Results: mm/cm/m; степень 4 применяет сам метод. Не передавайте mm4/cm4/m4. Пустая строка использует текущую output-длину."
    elif name == "seedPlane" and member["name"] == "SampleMaterialIntervals":
        meaning = "Signed нормальная координата опорной плоскости, мм, относительно начала section XY; это скаляр Double, не объект плоскости."
    elif name in PARAMETERS: meaning = PARAMETERS[name]
    elif re.fullmatch(r"(?:center|origin|point|start|end)?[XYxy][12]?", name): meaning = "Модельная координата " + name + ", мм; знаки соответствуют section XY/WCS."
    elif name in ("x", "y", "x1", "y1", "x2", "y2", "width", "height"): meaning = "Координата/размер " + name + ", мм; размеры width/height положительны."
    elif name in ("tangentX", "tangentY"): meaning = "Компонента единичной касательной, без размерности."
    elif name in ("nx", "ny"): meaning = "Компонента нормали/направления в section XY; вектор не нулевой."
    elif name in ("minimum", "maximum", "minStep", "maxStep", "minChord", "maxChord", "nMin", "nMax", "tMin", "tMax", "pathDistance", "rayDistance", "distance", "startDistance", "endDistance", "bound"):
        meaning = "Длина/станция/граница " + name + ", внутренние мм; направление и пределы задаёт выбранный запрос."
        if member["name"] == "OffsetRoundedPolygon": meaning = "Signed offset, мм: положительно внутрь площади, отрицательно наружу; это не left-offset обхода."
        if member["name"] == "Slice": meaning = "Станция вдоль полного пути, мм, в [0;Length]; endDistance строго больше startDistance."
    elif name in ("count", "stepCount", "openingCount", "probeCount", "baseCount"):
        meaning = "Целый неотрицательный счётчик; для ByCount применяется отдельно к каждому пути."
    elif name in ("A", "B"): meaning = "Число той же размерности, что второй аргумент; helper единицы не преобразует."
    elif name in ("first", "second"): meaning = "Первая/вторая сравниваемая готовая область."
    elif name in ("parameterMin", "parameterMax"): meaning = "Граница нормированного параметра выбранной линии/интервала."
    elif name in ("row2Diameter", "row3Diameter", "baseDiameter"): meaning = "Диаметр соответствующего ряда, мм≥0; 0 выключает дополнительный ряд."
    elif name in ("row2Binding", "row3Binding"): meaning = "Принятый selector связи соответствующего ряда; EachBar/EverySecondBar."
    elif name in ("closed", "incomingTangentAtJoint"): meaning = "Явный Boolean режима замыкания/касательной; не исправляет геометрию автоматически."
    elif name in ("result", "mesh", "rebars", "source", "seedPlane"): meaning = "Подготовленный объект/контейнер выбранного запроса, без повторного чтения Excel или назначения типа."
    elif name in ("value", "valueMm", "valueText"): meaning = "Входное/выходное скалярное значение в размерности операции; CUnitSystem задаёт единственный перевод."
    elif name in ("combinationID", "standard", "sourceType"): meaning = "Скалярная metadata владельца/источника; геометрическая классификация от строки не зависит."
    elif name == "axisDistance": meaning = "Положительное расстояние до оси, мм; не защитный слой до поверхности и не продольный setback."
    else: raise ValueError("Parameter meaning is missing: " + member["id"] + ": " + name)
    if passing == "ByRef": meaning += " ByRef: возвращаемые скаляры/буфер можно изменять, исходный immutable snapshot не меняется."
    return meaning
